-- 14245 Town-In-A-Box: aura 67854 (phase 1024) must stay while 14245 is in progress; quest_end_status 1 removed it on accept.
UPDATE `spell_area` SET `quest_end_status` = 11 WHERE `spell` = 67854 AND `area` = 4720 AND `quest_start` = 14326 AND `quest_end` = 14245 AND `quest_end_status` <> 11;
-- 24741 Trading Up / 24744 The Biggest Egg Ever: egg chests (GO 201974 x5, 201977 x1) in phase 1 while the raptors use 14336.
UPDATE `gameobject` SET `phaseMask` = 14336 WHERE `id` IN (201974, 201977) AND `phaseMask` = 1;

